from __future__ import annotations

from functools import wraps
from typing import Callable


class StateAllowed:

    CURRENT_STATE: dict[str, StateAllowed] = {}
    INIT: int = 0
    STARTED: int = 1
    ANY: int = 2

    def __init__(self, *allowed_states):
        self.allowed_states = []
        for each in allowed_states:
            self.allowed_states.append(getattr(StateAllowed, each))

    def __call__(self, func: Callable) -> Callable:
        def wrapper(*args, **kwargs):
            wraps(func)(self)
            alias = args[0].alias
            if (
                StateAllowed.ANY in self.allowed_states
                or StateAllowed.CURRENT_STATE[alias] in self.allowed_states
            ):
                return func(*args, **kwargs)

        return wrapper

    @classmethod
    def set_state(cls, new_state: str, alias: str | None = None) -> None:
        """Sets current state for specified alias."""
        cls.CURRENT_STATE[alias] = getattr(cls, new_state)
